// Shared by server and client code. Must match `leadStatus` in src/db/schema.ts
// (src/lib/admin/leads.ts checks this at compile time).

export const leadStatuses = ["new", "contacted", "consult_booked", "won", "lost"] as const;

export type LeadStatus = (typeof leadStatuses)[number];

export const leadStatusLabel: Record<LeadStatus, string> = {
  new: "New",
  contacted: "Contacted",
  consult_booked: "Consult booked",
  won: "Won",
  lost: "Lost",
};

/** Leads generated by `pnpm db:seed:demo` use the reserved example.com domain. */
export function isSampleLead(email: string) {
  return email.toLowerCase().endsWith("@example.com");
}

export function isLeadStatus(value: unknown): value is LeadStatus {
  return typeof value === "string" && (leadStatuses as readonly string[]).includes(value);
}
